#main #cnt, #cnt #center_col, #cnt #foot, .HdCKGe {
  width: calc(25.28vw + 340.65px); /** 1366=700px；1920=800px；2560=1000px **/
}

.MjjYud{
  animation-name: ani_topTobuttom;
  animation-duration: .3s;
  animation-timing-function: ease;
  width: 100%;
  align-items: stretch;
  justify-items: stretch;

  .jUmkFb:hover {
    margin: 0 auto;
    border-left: unset;
    padding: 0px 20px 15px;
    margin-bottom: 20px;
  }

  div[two-child],
  .A6K0A {

    a{
      color: #3476d2;

      h3 {
        position: relative;
        font-weight: bold;

        &:after {
          content: "";
          position: absolute;
          border-bottom: 2px solid #3476d2;
          bottom: -3px;
          left: 100%;
          width: 0;
          transition: width 350ms, left 350ms;
        }

        &:hover:after {
          left: 0;
          width: 100%;
          transition: width 350ms;
        }
      }

      &:visited {
        color: #660099;
      }
    }
    
    & > div{
      margin-top: 10px;
    }

    div.rc .s {
